import{_ as o,H as l,f as r,i as t}from"./chunks/framework.DLd0CbzH.js";const m=JSON.parse('{"title":"Архитектура системы сбора данных","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),a={name:"architecture.md"};function i(c,e,d,n,s,u){return l(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="архитектура-системы-сбора-данных" tabindex="-1">Архитектура системы сбора данных <a class="header-anchor" href="#архитектура-системы-сбора-данных" aria-label="Permalink to &quot;Архитектура системы сбора данных&quot;">​</a></h1><blockquote><p><strong>Устарело / superseded.</strong> Каноничный источник — <code>docs/03_Dev/Architecture.md</code> (краткая версия для AI-навигации — <code>docs/dev/architecture.md</code>). Имена моделей/таблиц ниже не сверены с текущим кодом (напр. <code>plt_parser_documents</code> удалён).</p></blockquote><p>Система построена на модульной архитектуре с четким разделением ответственности между общим ядром (Platform) и специфичными реализациями площадок (Eis, B2B и т.д.).</p><h2 id="терминология" tabindex="-1">Терминология <a class="header-anchor" href="#терминология" aria-label="Permalink to &quot;Терминология&quot;">​</a></h2><ol><li><strong>Platform (Платформа)</strong> — Объект, описывающий источник данных (например, ЕИС).</li><li><strong>Crawler (Профиль/Настройка)</strong> — Модель <code>Platform\\Models\\Crawling\\Crawler</code>. Содержит параметры поиска: фильтры, регионы, частоту обновлений. <ul><li><em>Таблица:</em> <code>plt_crawlers</code></li></ul></li><li><strong>Link (Результат обхода)</strong> — Модель <code>Platform\\Models\\Crawling\\Link</code>. Конкретная найденная закупка/лот на первом этапе. <ul><li><em>Таблица:</em> <code>plt_crawler_links</code></li></ul></li><li><strong>Document (Документ)</strong> — Модель <code>Platform\\Models\\Parser\\Document</code>. Файл, найденный внутри Link (смета, ТЗ, контракт). <ul><li><em>Таблица:</em> <code>plt_parser_documents</code></li></ul></li></ol><h2 id="схема-работы-workflow" tabindex="-1">Схема работы (Workflow) <a class="header-anchor" href="#схема-работы-workflow" aria-label="Permalink to &quot;Схема работы (Workflow)&quot;">​</a></h2><ol><li><p><strong>Stage 1: Crawling (Обход)</strong></p><ul><li>Сервис <code>AbstractCrawlingService</code> запускается для конкретного <code>Crawler</code>.</li><li>Находит новые объекты на источнике.</li><li>Формирует <code>LinkDto</code> и сохраняет их в <code>plt_crawler_links</code> со статусом <code>pending</code>.</li></ul></li><li><p><strong>Stage 2: Parsing (Анализ и разбор)</strong></p><ul><li>Воркер берет ссылки из <code>plt_crawler_links</code>.</li><li>Собирает список документов в <code>plt_parser_documents</code>.</li><li>Использует AI (Gemini) для классификации: является ли документ сметой.</li><li>Если да — извлекает позиции сметы в структурированный вид.</li></ul></li></ol>',7)])])}const p=o(a,[["render",i]]);export{m as __pageData,p as default};
